function render() {
	_update(0.9)
	var pg = 0

	render_cover(pg++)	
	render_breedIntro(pg++)
	render_breedAnalysis(pg++)
	render_wildcat(pg++)

  if (product_list.indexOf("health") != -1) {
  	render_healthIntro(pg++)
  	pg = render_healthMarkers(pg++)
  }

	render_healthAdvice(pg++)
	render_breedList(pg++)
	for (breed in data_origin) {
		render_breed(pg++,breed)
	}
	_update(0.6)
}

render();
